import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, useLocation, Navigate } from 'react-router-dom';

import Navbar from './Components/Navbar'; 
import Footer from './Components/Footer'; 
import ScrollToTop from './Components/ScrollToTop';
import Home from './Pages/Home';
import UserHome from './Pages/UserHome';
import Login from './Pages/Login';
import Steps from './Pages/Steps';
import About from './Pages/About';
import Result from './Pages/Result';
import Products from './Pages/Products';
import Scan from './Pages/Scan';
import Resources from './Pages/Resources';

function NavigationWrapper() {
  const location = useLocation();
  
  // 💡 حل مشكلة التحديث: تحويل حالة تسجيل الدخول إلى State حية تشعر بالتغيير فوراً
  const [isLoggedIn, setIsLoggedIn] = useState(localStorage.getItem('isLoggedIn') === 'true');

  // مراقبة تغييرات الصفحة لتحديث حالة الدخول والخروج بشكل مستمر ومزامنتها
  useEffect(() => {
    setIsLoggedIn(localStorage.getItem('isLoggedIn') === 'true');
  }, [location]);

  // 💡 حل مشكلة الـ HashRouter: الفحص الشامل لصفحة اللوجين سواء بالمسار العادي أو الهاش
  const isLoginPage = location.pathname === '/login' || location.hash === '#/login';

  return (
    <div className="flex flex-col min-h-screen">
      <ScrollToTop />
      
      {/* الـ Navbar يظهر فقط خارج صفحة اللوجين */}
      {!isLoginPage && <Navbar />}
      
      <main className={`flex-grow ${isLoginPage ? 'pt-0' : 'pt-20'}`}> 
        <Routes>
          {/* الصفحة الرئيسية: تتغير حياً فوراً بناءً على الـ State */}
          <Route path="/" element={isLoggedIn ? <UserHome /> : <Home />} />
          
          {/* صفحة اللوجين: لو المستخدم مسجل دخول بالفعل وجاء يفتحها، يتم توجيهه تلقائياً للرئيسية لمنع اللخبطة */}
          <Route path="/login" element={isLoggedIn ? <Navigate to="/" replace /> : <Login />} />
          
          {/* باقي مسارات الموقع المستقرة */}
          <Route path="/scan" element={<Scan />} />
          <Route path="/result" element={<Result />} />
          <Route path="/resources" element={<Resources />} /> 
          <Route path="/products" element={<Products />} />
          <Route path="/steps" element={<Steps />} />
          <Route path="/about" element={<About />} />
          
          {/* 💡 حماية إضافية: لو كتب أي مسار عشوائي خاطئ يتم إرجاعه للرئيسية بدل الشاشة البيضاء */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </main>

      {/* الـ Footer يظهر فقط خارج صفحة اللوجين */}
      {!isLoginPage && <Footer />}
    </div>
  );
}

function App() {
  return (
    <Router>
      <NavigationWrapper />
    </Router>
  );
}

export default App;